SELECT 'vehicle' AS kind, f.name, f.speed, f.driving, ROUND(ST_DISTANCE(w.geom,f.g)/1000,2) AS km_outside, NULL AS orders FROM fleet f, w WHERE ST_DISTANCE(w.geom,f.g) <= 2000
UNION ALL
SELECT 'customer', c.name, NULL, NULL, ROUND(ST_DISTANCE(w.geom,c.g)/1000,2), c.orders FROM cust c, w WHERE ST_DISTANCE(w.geom,c.g) <= 2000
ORDER BY kind DESC, km_outside, name